-- Create "budget_events" table
CREATE TABLE `budget_events` (`id` varchar(32) NOT NULL, `created_at` datetime(6) NOT NULL, `team_id` varchar(32) NOT NULL, `window_id` varchar(32) NOT NULL DEFAULT "", `request_id` varchar(32) NOT NULL DEFAULT "", `policy_id` varchar(32) NOT NULL DEFAULT "", `action_key` varchar(150) NOT NULL, `actor_id` varchar(32) NOT NULL DEFAULT "", `kind` enum('policy','reserve','settle','resolve') NOT NULL, `data` json NOT NULL, PRIMARY KEY (`id`), UNIQUE INDEX `action_key` (`action_key`), INDEX `budgetevent_team_id_created_at` (`team_id`, `created_at`), INDEX `budgetevent_window_id_created_at` (`window_id`, `created_at`)) CHARSET utf8mb4 COLLATE utf8mb4_bin;
-- Create "budget_gates" table
CREATE TABLE `budget_gates` (`id` varchar(32) NOT NULL, `created_at` datetime(6) NOT NULL, `revision` bigint NOT NULL DEFAULT 0, PRIMARY KEY (`id`)) CHARSET utf8mb4 COLLATE utf8mb4_bin;
-- Create "budget_policies" table
CREATE TABLE `budget_policies` (`id` varchar(32) NOT NULL, `created_at` datetime(6) NOT NULL, `updated_at` datetime(6) NOT NULL, `team_id` varchar(32) NOT NULL, `scope` enum('team','member','default_member','provider') NOT NULL, `subject_id` varchar(400) NOT NULL DEFAULT "", `period` enum('day','month') NOT NULL, `timezone` varchar(100) NOT NULL, `previous_timezone` varchar(100) NOT NULL DEFAULT "", `timezone_effective_at` datetime(6) NULL, `point_limit` bigint NULL, `input_limit` bigint NULL, `output_limit` bigint NULL, `total_limit` bigint NULL, `enabled` bool NOT NULL DEFAULT 1, `revision` bigint NOT NULL DEFAULT 1, PRIMARY KEY (`id`), UNIQUE INDEX `budgetpolicy_team_id_scope_subject_id_period` (`team_id`, `scope`, `subject_id`, `period`)) CHARSET utf8mb4 COLLATE utf8mb4_bin;
-- Create "budget_reservations" table
CREATE TABLE `budget_reservations` (`id` varchar(32) NOT NULL, `created_at` datetime(6) NOT NULL, `request_id` varchar(32) NOT NULL, `window_id` varchar(32) NOT NULL, `policy_id` varchar(32) NOT NULL, `policy_revision` bigint NOT NULL, `point_units` bigint NOT NULL DEFAULT 0, `input_tokens` bigint NOT NULL DEFAULT 0, `output_tokens` bigint NOT NULL DEFAULT 0, `unbounded` bool NOT NULL DEFAULT 0, `unpriced` bool NOT NULL DEFAULT 0, `settled` bool NOT NULL DEFAULT 0, PRIMARY KEY (`id`), UNIQUE INDEX `budgetreservation_request_id_window_id` (`request_id`, `window_id`), INDEX `budgetreservation_window_id_settled` (`window_id`, `settled`)) CHARSET utf8mb4 COLLATE utf8mb4_bin;
-- Create "budget_windows" table
CREATE TABLE `budget_windows` (`id` varchar(32) NOT NULL, `created_at` datetime(6) NOT NULL, `team_id` varchar(32) NOT NULL, `scope` enum('team','member','provider') NOT NULL, `subject_id` varchar(400) NOT NULL DEFAULT "", `period` enum('day','month') NOT NULL, `starts_at` datetime(6) NOT NULL, `ends_at` datetime(6) NOT NULL, `spent_units` bigint NOT NULL DEFAULT 0, `reserved_units` bigint NOT NULL DEFAULT 0, `spent_input` bigint NOT NULL DEFAULT 0, `reserved_input` bigint NOT NULL DEFAULT 0, `spent_output` bigint NOT NULL DEFAULT 0, `reserved_output` bigint NOT NULL DEFAULT 0, `unpriced_count` bigint NOT NULL DEFAULT 0, `unbounded_count` bigint NOT NULL DEFAULT 0, PRIMARY KEY (`id`), INDEX `budgetwindow_team_id_ends_at` (`team_id`, `ends_at`), UNIQUE INDEX `budgetwindow_team_id_scope_subject_id_period_starts_at` (`team_id`, `scope`, `subject_id`, `period`, `starts_at`)) CHARSET utf8mb4 COLLATE utf8mb4_bin;
